#include <iostream>
#include <string>
using namespace std;

int main() {
    int x;
    string d;

    if (!(cin >> x >> d)) return 0;

    int artsay = 0, eksay = 0;

    for (char c : d) {
        if (c == '+')
            ++artsay;
        else
            ++eksay;
    }

    if (d[0] == '+') {
        cout << max(0, artsay - eksay);
    } else {
        cout << artsay;
    }

    return 0;
}

